    function pickFile(cb) {
      const inp = el2("input", { type: "file", accept: ".json,application/json", style: "display:none" });
      inp.addEventListener("change", () => {
        const f = inp.files && inp.files[0];
        if (!f) return;
        const rd = new FileReader();
        rd.onload = () => cb(rd.result, f.name);
        rd.readAsText(f);
        inp.remove();
      });
      document.body.appendChild(inp);
      inp.click();
    }
    function download(filename, text) {
      const blob = new Blob([text], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = el2("a", { href: url, download: filename });
      document.body.appendChild(a);
      a.click();
      setTimeout(() => {
        a.remove();
        URL.revokeObjectURL(url);
      }, 100);
    }
    function loadExampleFlow() {
      const A = API3();
      if (A.hasExample() && !confirm("Reload the example world? Changes you made to it will be discarded.")) return;
      A.loadExample().then(() => {
        refreshPanel();
        toast("Example world loaded — enabled & ready. Just start chatting!");
      });
    }
    function importFlow() {
      const A = API3();
      pickFile(async (txt, name) => {
        try {
          const data = JSON.parse(txt);
          if (data && !Array.isArray(data) && Array.isArray(data.locations) && !data.entries && !data.spec) {
            const taken = data.id && A.listWorlds().some((x) => x.id === data.id);
            if (taken && !confirm(`A world with this id is already in your library ("${data.name || data.id}"). Import this one as a copy?`)) return;
            if (taken) {
              delete data.id;
              data.name = `${data.name || "World"} (imported)`;
            }
            await A.importWorld(data);
            toast(`Imported the world "${A.activeWorld().name}"`);
          } else {
            const book = A.readLorebook(data);
            const merge = book.world ? A.activeWorld() ? !confirm(`This lorebook holds the RPmod world "${book.world.name || "World"}".
OK = restore it as its own world.
Cancel = add its entries to the active world.`) : false : A.activeWorld() ? confirm("Merge into the active world?  (Cancel = create a new world)") : false;
            const count = await A.importLorebook(data, { merge, worldName: (name || "").replace(/\.json$/i, "") });
            toast(book.world && !merge ? `Restored the world "${A.activeWorld().name}" (${count} entries)` : `Imported ${count} entr${count === 1 ? "y" : "ies"}`);
          }
          refreshPanel();
          if (S2.root) {
            reloadGraph();
            fit2();
            draw2();
            renderInspector2();
          }
        } catch (e) {
          toast("Import failed: " + (e.message || e), true);
        }
      });
    }
    let exportOpen = false;
